  "skill": "MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND",
  "key_step": "The child finds the two thousands the number lies between and looks only at the hundreds digit to decide which is nearer.",
  "floor": {
   "prerequisite": "Rounds to the nearest hundred.",
   "question": "Round 2,470 to the nearest hundred.",
   "answer": "2,500"
  },
  "representations": [
   "a number line between two thousands with the halfway mark",
   "the number with the thousands digit circled and the hundreds digit underlined",
   "a newspaper figure for a crowd"
  ],
  "steps": [
   "Circle the thousands digit.",
   "Look at the hundreds digit only.",
   "5 or more: add one thousand; less than 5: keep the thousands.",
   "Write zeros in the hundreds, tens and ones."
  ],
  "contexts": [
   "a newspaper rounding a crowd",
   "the population of a town",
   "the price of a dairy cow"
  ],
  "board": [
   {
    "beat": "draw",
    "do": "Draw a number line from 67,000 to 68,000 with 67,500 in the middle."
   },
   {
    "beat": "point",
    "do": "Point at the halfway mark.",
    "say": "Is 67,449 before or after the middle?"
   },
   {
    "beat": "pause",
    "do": "Wait for the child to place 67,449."
   },
   {
    "beat": "reveal",
    "do": "Mark 67,449 just before the middle and write 67,000."
   }
  ],
  "misconceptions": [
   {
    "code": "MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_DOWN_ALWAYS",
    "listen_for": [
     "cut off the end",
     "38,000"
    ],
    "ask": "Is 38,700 nearer 38,000 or 39,000?",
    "repair": "Look at the hundreds digit: 5 or more rounds up.",
    "error": "Always drops the hundreds and lower digits to zero, never rounding up.",
    "example": {
     "question": "Round 38,700 to the nearest thousand.",
     "wrong_answer": "38,000",
     "correct_answer": "39,000"
    }
   },
   {
    "code": "MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_WRONG_DIGIT_LOOKED_AT",
    "listen_for": [
     "the 6 makes it go up",
     "tens digit"
    ],
    "ask": "Which digit is just to the right of the thousands digit?",
    "repair": "Only the hundreds digit decides when rounding to the nearest thousand.",
    "error": "Looks at the tens digit, not the hundreds digit, to decide whether to round up.",
    "example": {
     "question": "Round 24,460 to the nearest thousand.",
     "wrong_answer": "25,000 (looked at 6 in the tens)",
     "correct_answer": "24,000"
    }
   },
   {
    "code": "MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_ZEROS_DROPPED",
    "listen_for": [
     "39",
     "thirty-nine"
    ],
    "ask": "Is 39 about the same size as 38,700?",
    "repair": "Write the zeros: the rounded number is 39,000.",
    "error": "Rounds correctly but writes only the number of thousands.",
    "example": {
     "question": "Round 38,700 to the nearest thousand.",
     "wrong_answer": "39",
     "correct_answer": "39,000"
    }
   },
   {
    "code": "MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_NINE_ROUNDED_NO_CARRY",
    "listen_for": [
     "40,000",
     "the 9 becomes 0"
    ],
    "ask": "Which two thousands is 49,600 between?",
    "repair": "Rounding 49 thousands up gives 50 thousands.",
    "error": "Rounds a 9 in the thousands place up to 0 without adding 1 to the ten thousands.",
    "example": {
     "question": "Round 49,600 to the nearest thousand.",
     "wrong_answer": "40,000",
     "correct_answer": "50,000"
    }
   },
   {
    "code": "MATH.G6.NUMBER.WHOLE_NUMBERS.ROUND_NEAREST_THOUSAND.M_ROUND_IN_STEPS",
    "listen_for": [
     "first the tens then the hundreds",
     "67,450"
    ],
    "ask": "Which digit tells us, and what is it?",
    "repair": "Look at the hundreds digit once; do not round the other digits first.",
    "error": "Rounds the number one place at a time from the right, so a number just under halfway is rounded up.",
    "example": {
     "question": "Round 67,449 to the nearest thousand.",
     "wrong_answer": "68,000 (67,449 to 67,450 to 67,500 to 68,000)",
     "correct_answer": "67,000"
    }
   }
  ],
  "checks": [
   {
    "question": "Round 67,449 to the nearest thousand.",
    "answer": "67,000",
    "shows": "one look at the hundreds digit"
   },
   {
    "question": "Round 49,600 to the nearest thousand.",
    "answer": "50,000",
    "shows": "carry into ten thousands"
   }
  ],
  "name": "Round numbers up to 100,000 to the nearest thousand",
